package dev.lps;

import javax.inject.Inject;

import com.google.inject.Provides;

import dev.lps.config.RevenantEtherLootTrackerConfig;
import dev.lps.ui.RevenantEtherLogOverlay;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MessageNode;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.QuantityFormatter;

@Slf4j
@PluginDescriptor(
    name = "Revenant Ether Loot Tracker",
    description = "Tracks revenant ether, even after the collection log stops!",
    tags = {"revenants", "revs", "ether", "tracker"}
)
public class RevenantEtherLootTrackerPlugin extends Plugin
{
    public static final long UNSIGNED_SHORT_MAX_VALUE = 0xFFFF;
    private static final String TARGET_MESSAGE_PREFIX = "You have received ";
    private static final String TARGET_MESSAGE_SUFFIX = " x Revenant ether.";

    @Getter
    @Inject
    private Client client;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    private ConfigManager configManager;

    @Inject
    private OverlayManager overlayManager;

    @Getter
    @Inject
    private RevenantEtherLootTrackerConfig config;

    @Inject
    private RevenantEtherLogOverlay revenantEtherLogOverlay;

    @Getter
    private long totalRevenantEtherLooted = 0L;

    @Provides
    RevenantEtherLootTrackerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(RevenantEtherLootTrackerConfig.class);
    }

    @Override
    protected void startUp() throws Exception
    {
        /**
         * It is possible for players to install plugins while logged out, so we will attempt to send
         * the warning message on startup/install but will abort if the player is not logged in.
         */
        sendWarningMessageIfNecessary(client.getGameState());
        totalRevenantEtherLooted = config.totalRevenantEtherLooted();
        overlayManager.add(revenantEtherLogOverlay);
    }

    @Override
    protected void shutDown() throws Exception
    {
        overlayManager.remove(revenantEtherLogOverlay);
    }

    @Subscribe
    public void onChatMessage(ChatMessage chatMessage)
    {
        if (
            config.displayRevenantEtherCollectionLogOverlay() == false
            || totalRevenantEtherLooted <= UNSIGNED_SHORT_MAX_VALUE
            || chatMessage.getType() != ChatMessageType.GAMEMESSAGE
        )
        {
            return;
        }

        MessageNode messageNode = chatMessage.getMessageNode();
        String message = messageNode.getValue();
        if (
            message.startsWith(TARGET_MESSAGE_PREFIX)
            && message.endsWith(TARGET_MESSAGE_SUFFIX)
        )
        {
            String newMessage = TARGET_MESSAGE_PREFIX + QuantityFormatter.formatNumber(totalRevenantEtherLooted) + TARGET_MESSAGE_SUFFIX;
            messageNode.setValue(newMessage);
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        /**
         * This will listen for any changes to the tracker in the configuration and apply them to the
         * internal tracker immediately. This will fix the issue with resetting the plugin not being
         * reflected in the UI.
         */
        if (
            event.getGroup().equals(RevenantEtherLootTrackerConfig.CONFIG_GROUP)
            && event.getKey().equals(RevenantEtherLootTrackerConfig.TOTAL_REVENANT_ETHER_LOOTED_KEY)
        )
        {
            totalRevenantEtherLooted = config.totalRevenantEtherLooted();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged gameStateChanged)
    {
        // This is a catch-all in the event that the player did not receive the warning message on startup/install
        sendWarningMessageIfNecessary(gameStateChanged.getGameState());
    }

    @Subscribe
    public void onLootReceived(LootReceived event)
    {
        long revenantEtherLooted = 0L;

        for (ItemStack itemStack : event.getItems())
        {
            if (itemStack.getId() == ItemID.WILD_CAVE_SHARD)
            {
                revenantEtherLooted = itemStack.getQuantity();
                break;
            }
        }

        if (revenantEtherLooted > 0L)
        {
            totalRevenantEtherLooted += revenantEtherLooted;
            updateConfig();
        }
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event)
    {
        if (event.getScriptId() == ScriptID.COLLECTION_DRAW_LIST)
        {
            try
            {
                syncWithCollectionLog();
            }
            catch (IllegalStateException __)
            {
                // Do nothing.
            }
        }
    }

    /**
     * Sends a warning message on installion about the need to sync the internal tracker with the collection log.
     * It is possible for users to install the plugin while logged out, so we must verify the game state before
     * attempting to send the warning messages.
     *
     * @param gameState
     */
    private void sendWarningMessageIfNecessary(GameState gameState)
    {
        if (
            config.hasSeenCollectionLogSyncWarning() == false
            && gameState == GameState.LOGGED_IN
        )
        {
            chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.GAMEMESSAGE).runeLiteFormattedMessage(ColorUtil.wrapWithColorTag("Revenant Ether Loot Tracker Plugin: Please open the revenant section of your collection log to sync the tracker! Failure to do so will result in any progress since installion being overwritten!", ColorScheme.PROGRESS_ERROR_COLOR)).build());
            configManager.setConfiguration(RevenantEtherLootTrackerConfig.CONFIG_GROUP, RevenantEtherLootTrackerConfig.HAS_SEEN_COLLECTION_LOG_SYNC_WARNING_KEY, true);
        }
    }

    /**
     * Attempts to sync our custom revenant ether tracker with the number of
     * revenant ether shown in the collection log.
     *
     * @implNote This function is reliant on the collection log interface being
     *           present, one way of ensuring this is to
     *           listen for the `ScriptID.COLLECTION_DRAW_LIST` script to finish.
     * @throws IllegalStateException When this method is invoked when the collection
     *                               log interface is either not
     *                               present or ready.
     */
    private void syncWithCollectionLog() throws IllegalStateException
    {
        /**
         * Safety check: If our custom tracker is already past the 16-bit limit,
         * we never need to trust or look at the collection log window ever again.
         */
        if (totalRevenantEtherLooted >= UNSIGNED_SHORT_MAX_VALUE)
        {
            return;
        }

        Widget collectionLogItems = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
        if (collectionLogItems == null)
        {
            throw new IllegalStateException(
                "This method must only be called after the collection log interface is ready!"
            );
        }

        for (Widget item : collectionLogItems.getChildren())
        {
            if (item.getItemId() != ItemID.WILD_CAVE_SHARD)
            {
                continue;
            }

            int collectionLogQuantity = item.getItemQuantity();
            if (collectionLogQuantity > totalRevenantEtherLooted)
            {
                chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.GAMEMESSAGE).runeLiteFormattedMessage(ColorUtil.wrapWithColorTag("Revenant Ether Loot Tracker Plugin: The tracker has been successfully synced with your collection log!", ColorScheme.PROGRESS_COMPLETE_COLOR)).build());
                totalRevenantEtherLooted = collectionLogQuantity;
                updateConfig();
            }
            break;
        }
    }

    private void updateConfig()
    {
        configManager.setConfiguration(RevenantEtherLootTrackerConfig.CONFIG_GROUP, RevenantEtherLootTrackerConfig.TOTAL_REVENANT_ETHER_LOOTED_KEY, totalRevenantEtherLooted);
    }
}

package dev.lps.ui;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;

import javax.inject.Inject;

import dev.lps.RevenantEtherLootTrackerPlugin;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.QuantityFormatter;

public class RevenantEtherLogOverlay extends WidgetItemOverlay
{
    @Inject
    private RevenantEtherLootTrackerPlugin plugin;

    public RevenantEtherLogOverlay()
    {
        super();

        // This ensures your custom drawings are layered cleanly on top of interface graphics
        drawAfterInterface(InterfaceID.COLLECTION);
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
    {
        /**
         * If the custom tracker hasn't surpassed the maximum 16-bit capacity yet,
         * let the game's native UI display the itemQuantitys naturally and exit early.
         */
        if (
            plugin.getConfig().displayRevenantEtherCollectionLogOverlay() == false
            || plugin.getTotalRevenantEtherLooted() <= RevenantEtherLootTrackerPlugin.UNSIGNED_SHORT_MAX_VALUE
        )
        {
            return;
        }

        if (itemId != ItemID.WILD_CAVE_SHARD)
        {
            return;
        }

        Rectangle canvasBounds = widgetItem.getCanvasBounds();

        // Give the item slot a black transparent background
        Color backgroundColor = new Color(0, 0, 0, 50);
        graphics.setColor(backgroundColor);
        graphics.fill3DRect((int) canvasBounds.getX(), (int) canvasBounds.getY(), (int) canvasBounds.getWidth(), (int) canvasBounds.getHeight(), false);

        long itemQuantity = plugin.getTotalRevenantEtherLooted();
        String textToDraw = QuantityFormatter.quantityToStackSize(itemQuantity);

        // Position text near the bottom left
        int textX = (int) canvasBounds.getX() + 1;
        int textY = (int) canvasBounds.getMaxY() - 1;

        // Render shadow first to ensure the numbers are easily readable over dark icons
        graphics.setFont(FontManager.getRunescapeSmallFont());
        graphics.setColor(Color.BLACK);
        graphics.drawString(textToDraw, textX + 1, textY + 1);

        // Render actual foreground numbers
        Color textColor = getStackColor(itemQuantity);
        graphics.setColor(textColor);
        graphics.drawString(textToDraw, textX, textY);
    }

    /**
     * Returns the native in-game color based on the given item quantity.
     *
     * @param itemQuantity
     * @return The native in-game color of text that corresponds to the given item quantity
     */
    private Color getStackColor(long itemQuantity)
    {
        if (itemQuantity >= 10_000_000L)
        {
            return ColorScheme.PROGRESS_COMPLETE_COLOR;
        }
        if (itemQuantity >= 100_000L)
        {
            return Color.WHITE;
        }
        return Color.YELLOW;
    }
}

package dev.lps.config;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("revenantEtherLootTracker")
public interface RevenantEtherLootTrackerConfig extends Config
{
    public final static String CONFIG_GROUP = "revenantEtherLootTracker";
    public final static String HAS_SEEN_COLLECTION_LOG_SYNC_WARNING_KEY = "hasSeenCollectionLogSyncWarning";
    public final static String TOTAL_REVENANT_ETHER_LOOTED_KEY = "totalRevenantEtherLooted";

    @ConfigItem(
        keyName = "displayRevenantEtherCollectionLogOverlay",
        name = "Display Collection Log Overlay",
        description = "Present overlay over the revenant ether item slot shown in the collection log",
        position = 1
    )
    default boolean displayRevenantEtherCollectionLogOverlay()
    {
        return true;
    }

    @ConfigItem(
        keyName = HAS_SEEN_COLLECTION_LOG_SYNC_WARNING_KEY,
        name = "Seen Collection Log Sync Warning",
        description = "Whether or not the player has seen the warning about syncing the internal tracker with the collection log",
        hidden = true
    )
    default boolean hasSeenCollectionLogSyncWarning()
    {
        return false;
    }

    @ConfigItem(
        keyName = TOTAL_REVENANT_ETHER_LOOTED_KEY,
        name = "Total Revenant Ether Looted",
        description = "The total amount of revenant ether received as drops",
        hidden = true
    )
    default long totalRevenantEtherLooted()
    {
        return 0L;
    }
}
